struct Aggregate {
    int i = 1;
    int j;      // No DMI (default initialized to 0)
    int k = 42;
};

// 1. Explicit Initialization (DMIs ignored)
Aggregate a = { 10, 20, 30 }; // i=10, j=20, k=30

// 2. Partial Initialization
// Unlisted members use DMIs or are zero-initialized
Aggregate b = { 5 };          // i=5, j=0, k=42

// 3. Empty Initialization
Aggregate c = {};             // i=1, j=0, k=42
